procedure SignsSignOrderReminders {
  about "Remind each client about their sign order"
  policy SignsPolicy
  sheet SignOrders "SignOrders" { client: Text, email: Email, due_on: Date, status: Text, quote: Money, proof_notes: Text private }
  trigger every friday at 11:00

  let all = fetch SignOrders
  let due = filter all where due_on == today() + 2 days and status == "ordered"
  let msgs = draft each r in due up to 100 email to r.email subject "Your sign order in two days": "Hi {r.client}, a reminder from the shop: your sign order is in two days."
  let ok = request batch approval of msgs from owner timeout 12 hours else stop "batch not approved"
  send ok
  for each r in due up to 100 {
    update r set status = "notified"
  }
}

