procedure DaycareOutreachCampaign {
  about "On request, contact recent paused familys"
  policy DaycarePolicy
  sheet Families "Families" { parent: Text, email: Email, due_date: Date, status: Text, balance: Money, health_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Families
  let targets = filter all where status == "paused" and days_between(due_date, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.parent}, come back to the daycare! Use code WELCOME10 on your next visit."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

