procedure BookstoreWinBack {
  about "Nudge customers whose hold was long ago"
  policy BookstorePolicy
  sheet Holds "Holds" { customer: Text, email: Email, held_until: Date, status: Text, prepaid: Money, phone_note: Text private }
  trigger every tuesday at 09:00

  let all = fetch Holds
  let old = filter all where days_between(held_until, today()) >= 90 and status != "expired"
  let oldest = sort old by held_until first 20
  for each r in oldest up to 20 {
    let m = draft email to r.email subject "We miss you": "Hi {r.customer}, it's been a while! We'd love to see you again at the store."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
  notify owner "Please update my business partner yourself."
}

