procedure GymFrozenFollowUp {
  about "Follow up with members marked frozen"
  policy GymPolicy
  sheet Members "Members" { name: Text, email: Email, renews_on: Date, status: Text, dues: Money, health_notes: Text private }
  trigger every friday at 18:00

  let all = fetch Members
  let recent = filter all where status == "frozen" and days_between(renews_on, today()) <= 2 and days_between(renews_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no frozen members"
