  notify owner "Frozen members to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.name default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

