policy:
policy BookstoreStockPolicy {
  allow read Inventory(title, copies, minimum, reorder_qty, distributor, unit_cost)
  allow supplier Inventory.distributor
  limit order $250 per action
  limit order $1000 per day
}

program:
procedure BookstoreReorder {
  about "Reorder books below their minimum"
  policy BookstoreStockPolicy
  sheet Inventory "Inventory" { title: Text, copies: Number, minimum: Number, reorder_qty: Number, distributor: Text, unit_cost: Money }
  trigger every tuesday at 11:00

  let all = fetch Inventory
  let low = filter all where copies < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $250.00 {
      notify owner "Reorder of {i.title} would cost {cost}, over the $250 limit."
      skip
    }
    order "{i.reorder_qty} x {i.title}" from i.distributor cost cost, ask owner first timeout 12 hours else skip
    log "ordered {i.title}"
  }
}

