procedure FilmlabRefunds {
  about "Handle refund requests within limits"
  policy FilmlabRefundPolicy
  sheet RefundRequests "RefundRequests" { request_id: Text, photographer: Text, email: Email, amount: Money, purchased: Date, status: Text }
  trigger when new row r in RefundRequests

  if days_between(r.purchased, today()) > 60 {
    notify owner "Refund request {r.request_id} is older than 60 days."
    stop "outside refund window"
  }
  if r.amount > $40.00 {
    notify owner "Refund request {r.request_id} is {r.amount}, over $40. Please review."
    stop "over refund limit"
  }
  if r.amount <= $15.00 {
    refund r.amount for r.request_id reason "refund request"
  } else {
    refund r.amount for r.request_id reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  }
  update r set status = "refunded"
  let m = draft email to r.email subject "Your refund": "Hi {r.photographer}, your refund of {r.amount} has been issued."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}

