policy:
policy RetailStockPolicy {
  allow read Stock(product, qty, min_qty, reorder_qty, vendor, cost)
  allow supplier Stock.vendor
  limit order $150 per action
  limit order $450 per day
}

program:
procedure RetailReorder {
  about "Reorder products below their minimum"
  policy RetailStockPolicy
  sheet Stock "Stock" { product: Text, qty: Number, min_qty: Number, reorder_qty: Number, vendor: Text, cost: Money }
  trigger every monday at 08:00

  let all = fetch Stock
  let low = filter all where qty < min_qty
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.cost
    if cost > $150.00 {
      notify owner "Reorder of {i.product} would cost {cost}, over the $150 limit."
      skip
    }
    order "{i.reorder_qty} x {i.product}" from i.vendor cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.product}"
  }
}

